#!/usr/bin/env python3
"""Guarded, atomic-as-practicable V1.2 -> V2 site upgrade on Linux Mint.
Does NOT commit/push, change branches/remotes, or claim a domain.
"""
from pathlib import Path
import hashlib,json,subprocess,sys,shutil,tempfile,os

SOURCE=Path(__file__).resolve().parent.parent
HOME=Path.home()
TARGET=HOME/'Development'/'the-four-season-wiki'
BACKUPS=HOME/'Downloads'
CODE_FILES=['index.html','404.html','assets/app.js','assets/atlas.js','assets/style.css','README.md',
 'tools/verify_linux.sh','tools/preview_linux.sh','tools/publish_linux.sh','tools/check_content.py',
 'tools/build_seed.py','tools/smoke_test.py','tools/install_upgrade_linux.sh','tools/upgrade_v2.py']
DATA_FILE='data/pages.json'
ART_DIR='assets/uploads'
V1_DIR=Path(__file__).resolve().parent.parent.parent/'daughter-of-the-moon-wiki' # packaged baseline may be absent on the PC
# Embed hashes of V1.2 distribution files to avoid depending on another ZIP.
V1_HASHES={'index.html': ['227a6eea98fc7212e1f428fcbd13d8be2b02cc6093a9ba4a1f9f976a7a568e3e'], 'assets/app.js': ['82fa506efd072b422d4236011d603e960ea27a6cb9ee4fff9270900cda56b6c1'], 'assets/style.css': ['21224ff390d874f18bcfa57462319b1848dce1fdcd4360f99cf616596b3124aa'], 'README.md': ['81689681da868b0d86e6231fc0ba557f81cf8fd178a7a109a7cdc898283d564d'], 'tools/verify_linux.sh': ['78fcc3ec4609df3da733e1b999350a61603bba9372ae0e5f6f3e686642071cba'], 'tools/preview_linux.sh': ['8443ccd5a34a5f2da7a5929d81dc71510bd033b31f28dd8c5f74c319c382dacf'], 'tools/publish_linux.sh': ['1416274f7343c51d143e60d13d8ade5ca407d944e2011935790494c289f44b5b'], 'tools/check_content.py': ['8c668b5a77743096e738eb76f6cedb82e15cad7ab814dbdf526e936591f06b07'], 'tools/build_seed.py': ['4e76e82441a36234284ec62b690fa53d5722249e14688649242dac5824a1b860'], 'tools/smoke_test.py': ['9d32cbe1a47b2425269ba500cc5dfac1b1e187ff16da05782f5a5d3fb42891f5'], 'tools/install_upgrade_linux.sh': ['349c4fa27108705189992c46f40539f258b1164d258add8ab9017a698507bb05']}
V1_PAGES=['the-four-seasons', 'campaign-chronicle', 'bramwell-elixor', 'luna', 'bjorn', 'fenwick', 'jimsko', 'yulia', 'arven', 'cinder', 'grath', 'velka', 'wiwi', 'brick', 'estephan', 'port-llast', 'net-and-keg', 'lighthouse', 'caverns-lior', 'neverwinter', 'luskan', 'sword-coast', 'kestrel-ford', 'thamor', 'crown-square', 'mourktar', 'blackreach', 'selune', 'shar', 'helm', 'moon-scroll', 'dragons-due', 'how-to-use']

def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def subprocess_check(args,cwd,**kwargs):return subprocess.run(args,cwd=cwd,check=True,**kwargs)
def git_output(*args):return subprocess.check_output(['git',*args],cwd=TARGET,stderr=subprocess.STDOUT).decode().strip()
def is_inside(path,base):
 try:path.resolve().relative_to(base.resolve());return True
 except ValueError:return False

def read_data(path):
 data=json.loads(path.read_text(encoding='utf-8'))
 if data.get('schema')!=1 or not isinstance(data.get('pages'),list):raise RuntimeError('Unexpected article data schema')
 if not any(p.get('id')=='the-four-seasons' and p.get('category')=='Party' for p in data['pages']):raise RuntimeError('Four Seasons party entry missing')
 return data

def merge_data(current,seed,baseline):
 merged=dict(current)
 newbyid={p['id']:p for p in seed['pages']}
 existing={p['id']:p for p in current['pages']}
 for ident,new in newbyid.items():
  if ident not in existing:
   if ident not in V1_PAGES:existing[ident]=new # respect intentionally deleted baseline pages
   continue
  old=existing[ident]
  if ident in baseline and old==baseline[ident]:
   existing[ident]=new # safely refresh unchanged stock article, e.g. add portrait
  # Never replace or discard a user-edited page.
 merged['pages']=list(existing.values())
 merged['siteName']='Daughter of the Moon Wiki'
 merged['atlas']=current.get('atlas') or seed['atlas']
 merged['quests']=current.get('quests') if isinstance(current.get('quests'),list) else []
 return merged

def main():
 print('=== DAUGHTER OF THE MOON WIKI V2 — SAFE INSTALL / UPGRADE ===')
 subprocess_check(['python3','tools/check_content.py'],cwd=SOURCE)
 if not TARGET.is_dir() or TARGET.is_symlink():raise RuntimeError(f'Expected existing, non-symlink wiki directory: {TARGET}')
 current=read_data(TARGET/DATA_FILE);seed=read_data(SOURCE/DATA_FILE)
 if not (TARGET/'.git').is_dir():raise RuntimeError('Existing wiki must have its published Git history; first publish V1 before upgrading')
 branch=git_output('branch','--show-current')
 if branch!='main':raise RuntimeError('STOP: Expected main branch; found '+branch)
 remote=git_output('remote','get-url','origin')
 trusted={'https://github.com/nickdosc/the-four-season-wiki','https://github.com/nickdosc/the-four-season-wiki.git','git@github.com:nickdosc/the-four-season-wiki','git@github.com:nickdosc/the-four-season-wiki.git'}
 if remote not in trusted:raise RuntimeError('STOP: Git remote does not match published wiki')
 # Refuse any preexisting local work to avoid accidental inclusion of unrelated modifications.
 status=git_output('status','--porcelain','--untracked-files=all')
 if status:raise RuntimeError('STOP: Existing local changes are present. Preserve/commit them before this upgrade:\n'+status[:1600])
 print('PASS: Git working tree clean and expected remote/branch')
 print('Checking that the published branch has not moved ahead...')
 subprocess_check(['git','fetch','--quiet','origin','main'],cwd=TARGET)
 if git_output('rev-parse','HEAD')!=git_output('rev-parse','origin/main'):
  raise RuntimeError('STOP: Remote and local branches differ. No files touched. Reconcile with GitHub first.')
 print('PASS: Local main matches origin/main')
 for rel in CODE_FILES:
  src=SOURCE/rel;dst=TARGET/rel
  if not src.is_file():raise RuntimeError('Missing V2 source '+rel)
  if dst.exists():
   if dst.is_symlink() or not dst.is_file():raise RuntimeError('STOP: Unexpected existing path '+rel)
   allowed=set(V1_HASHES.get(rel,[]))|{sha(src)}
   if sha(dst) not in allowed:raise RuntimeError('STOP: Modified theme/tool file: '+rel+'; manual review required before upgrade')
 if (TARGET/'CNAME').read_text().strip()!='daughterofthemoon.quest' if (TARGET/'CNAME').exists() else False:
  raise RuntimeError('STOP: Existing custom domain differs')
 for asset in (SOURCE/ART_DIR).glob('*'):
  dst=TARGET/ART_DIR/asset.name
  if dst.is_symlink() or (dst.exists() and sha(dst)!=sha(asset)):
   raise RuntimeError('STOP: A supplied illustration conflicts with your existing file: '+asset.name)
 baseline=V1_BASELINE_DATA()
 updated=merge_data(current,seed,baseline)
 # Preflight merged output in a temporary directory without modifying the actual site.
 tmp=Path(tempfile.mkdtemp(prefix='daughter-v2-preflight-',dir=HOME/'Downloads'))
 try:
  shutil.copytree(SOURCE,tmp,dirs_exist_ok=True,ignore=shutil.ignore_patterns('_previews','__pycache__'))
  (tmp/DATA_FILE).write_text(json.dumps(updated,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
  for p in updated['pages']:
   if p.get('cover') and str(p['cover']).startswith(ART_DIR+'/') and not (tmp/p['cover']).exists() and (TARGET/p['cover']).exists():
    dest=tmp/p['cover'];dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(TARGET/p['cover'],dest)
  subprocess_check(['python3','tools/check_content.py'],cwd=tmp)
  print('PASS: Preflight merged content and related references')
 finally:shutil.rmtree(tmp)
 BACKUPS.mkdir(exist_ok=True)
 backup=Path(tempfile.mkdtemp(prefix='daughter-wiki-before-v2-',dir=BACKUPS))
 paths=CODE_FILES+[DATA_FILE]+[str(f.relative_to(SOURCE)) for f in (SOURCE/ART_DIR).glob('*') if f.is_file()]
 existed={rel:(TARGET/rel).exists() for rel in paths}
 for rel in paths:
  src=TARGET/rel
  if existed[rel]:
   dest=backup/rel;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(src,dest)
 try:
  for rel in CODE_FILES:
   src=SOURCE/rel;dest=TARGET/rel;dest.parent.mkdir(parents=True,exist_ok=True)
   with tempfile.NamedTemporaryFile(delete=False,dir=dest.parent) as out:
    temp=Path(out.name);out.write(src.read_bytes())
   temp.chmod(src.stat().st_mode);temp.replace(dest)
  for asset in (SOURCE/ART_DIR).glob('*'):
   dest=TARGET/ART_DIR/asset.name;dest.parent.mkdir(parents=True,exist_ok=True)
   if not dest.exists():shutil.copy2(asset,dest)
  dest=TARGET/DATA_FILE
  with tempfile.NamedTemporaryFile(delete=False,dir=dest.parent) as out:
   temp=Path(out.name);out.write((json.dumps(updated,indent=2,ensure_ascii=False)+'\n').encode())
  temp.replace(dest)
  subprocess_check(['python3','tools/check_content.py'],cwd=TARGET)
  subprocess_check(['bash','tools/verify_linux.sh'],cwd=TARGET)
 except BaseException:
  print('UPGRADE ERROR: restoring pre-upgrade files from backup')
  for rel in paths:
   dest=TARGET/rel
   if existed[rel]:shutil.copy2(backup/rel,dest)
   elif dest.exists():dest.unlink()
  raise
 print('PASS: V2 installed safely, leaving Git history, remote, articles, and custom domain untouched.')
 print('Backup:',backup)
 print('NO COMMIT OR PUSH WAS PERFORMED.')

def V1_BASELINE_DATA():
 # Embedded exact V1.2 records, to detect untouched defaults without overwriting edits.
 return {p['id']:p for p in [{'id': 'the-four-seasons', 'title': 'The Four Seasons', 'category': 'Party', 'summary': 'A band of travelers whose paths have become entwined with the fate of kingdoms, moonlight, and shadow.', 'body': "# A name forged on the road\nThe **Four Seasons** is the name adopted by the adventuring party during their travels through [[Kestrel Ford]]. Their story began far to the north, in [[Port Llast]], where an investigation at the [[Port Llast Lighthouse]] led them into a mystery involving [[Selûne]], [[Shar]], and the [[Moon Scroll]].\n\n## The adventurers\nThe company has included [[Bramwell Elixor]], [[Luna]], [[Bjorn]], and [[Fenwick]]. Allies met along the way include [[Jimsko]], [[Brick]], and [[Estephan]].\n\n## A widening world\nWhat began on the Sword Coast has carried the travelers through [[Neverwinter]] and toward [[Thamor]], where politics and a looming threat known as the [[Dragon's Due]] have begun to cast a long shadow.\n\n> Some legends begin with a prophecy. Others begin with a few strangers choosing to walk the same road.\n\n## Chronicle\nRead the [[Campaign Chronicle]] for the group's journey so far.", 'cover': '', 'aliases': ['Four Seasons', 'the party'], 'facts': [['Campaign', 'The Daughter of the Moon'], ['Region', 'Sword Coast and beyond'], ['First_chapter', 'Port Llast']], 'icon': '❖'}, {'id': 'campaign-chronicle', 'title': 'Campaign Chronicle', 'category': 'Chronicle', 'summary': 'A player-friendly record of the travels and turning points of The Four Seasons.', 'body': "# A chronicle of the road\n## Chapter I — The light at Port Llast\nThe adventurers arrived at [[Port Llast]], spoke with its people, and uncovered unsettling events surrounding the [[Port Llast Lighthouse]]. Their travels brought them into the [[Caverns of Lior]] and into possession of the mysterious [[Moon Scroll]].\n\n## Chapter II — The road to Neverwinter\nFollowing the events in Port Llast, the party traveled toward [[Neverwinter]], a city of crowns, traders, and uneasy loyalties. There, their discoveries drew greater attention.\n\n## Saga II — The roads of Threskel\nThe group continued toward [[Kestrel Ford]], where they adopted the name [[The Four Seasons]]. The journey eventually led them into [[Thamor]] and its crowded streets, as the young [[King Arven I]] prepared to preside over a knighting ceremony.\n\n## Most recently\nAt the celebration in [[Thamor]], an attempted attack disturbed the ceremony. The city now stands at the intersection of royal ambition, rival claims, and the threat of the [[Dragon's Due]].\n\n*This chronicle records the broad strokes of events known to the party. Individual entries can be expanded after each session.*", 'cover': '', 'aliases': [], 'facts': [['Format', 'Player-safe session history'], ['Current_arc', 'Saga II — Thamor']], 'icon': '⌛'}, {'id': 'bramwell-elixor', 'title': 'Bramwell Elixor', 'category': 'Characters', 'summary': 'A human cleric of Helm whose convictions have drawn both admiration and controversy.', 'body': '# The watchful hand\n**Bramwell Elixor** is a human cleric devoted to [[Helm]]. A practiced alchemist as well as a priest, he has walked a difficult line between faith, responsibility, and what he believes to be right.\n\nBramwell became known for his efforts to help those afflicted by a terrible plague. That work, and the choices surrounding it, have complicated his relationship with religious authority.\n\n## Travels\nA founding member of [[The Four Seasons]], Bramwell has journeyed through [[Port Llast]], [[Neverwinter]], and [[Thamor]]. During the knighting ceremony in Thamor, he reacted to an arrow aimed into the gathering.\n\n## Known connections\n- [[Helm]] — god of guardians and vigilance\n- [[The Four Seasons]] — his companions\n- [[Luna]] and [[Bjorn]] — fellow adventurers', 'cover': '', 'aliases': [], 'facts': [['Ancestry', 'Human'], ['Calling', 'Cleric'], ['Faith', 'Helm'], ['Association', 'The Four Seasons']], 'icon': '⚔'}, {'id': 'luna', 'title': 'Luna', 'category': 'Characters', 'summary': 'A wanderer whose story is still unfolding, with strange dreams and ties to the world of the fey.', 'body': "# A life written in questions\n**Luna** travels with [[The Four Seasons]]. Mysterious dreams, unusual encounters, and the pull of the fey have followed her adventures.\n\nOnce known for her roguish talents, Luna's journey has taken her toward strange magic and a personal history that is not yet fully understood.\n\n## On the road\nLuna has traveled alongside [[Bramwell Elixor]] and [[Bjorn]] through [[Port Llast]], [[Neverwinter]], and the lands around [[Thamor]].\n\n## A living entry\nMore of Luna's history will be added as it becomes part of the shared campaign story.", 'cover': '', 'aliases': [], 'facts': [['Association', 'The Four Seasons'], ['Known_for', 'Unusual dreams and fey encounters']], 'icon': '☾'}, {'id': 'bjorn', 'title': 'Bjorn', 'category': 'Characters', 'summary': 'A towering goliath barbarian, formidable in battle and loyal to his companions.', 'body': '# Strength on the road\n**Bjorn** is a goliath warrior and a member of [[The Four Seasons]].\n\nA son of [[Jimsko]], Bjorn carries his strength and resolve through each hard-won adventure, from the shores near [[Port Llast]] to the roads beyond [[Neverwinter]].\n\nHis story is closely entwined with those of [[Bramwell Elixor]], [[Luna]], and their fellow travelers.', 'cover': '', 'aliases': [], 'facts': [['Ancestry', 'Goliath'], ['Calling', 'Barbarian'], ['Family', 'Jimsko'], ['Association', 'The Four Seasons']], 'icon': '✊'}, {'id': 'fenwick', 'title': 'Fenwick', 'category': 'Characters', 'summary': 'A gnome druid, also known as Xero, who once traveled with the company.', 'body': '# The druid of the wilds\n**Fenwick**, sometimes called **Xero**, is a gnome druid and a former traveling member of [[The Four Seasons]].\n\nHis familiarity with the natural world brought a different outlook to the group during their journeys. His road has since separated from the company’s, though his part in their history remains.\n\nSee also: [[Campaign Chronicle]].', 'cover': '', 'aliases': ['Xero'], 'facts': [['Ancestry', 'Gnome'], ['Calling', 'Druid'], ['Status', 'Former companion']], 'icon': '❀'}, {'id': 'jimsko', 'title': 'Jimsko', 'category': 'Characters', 'summary': 'A dwarf with longstanding ties to the adventurers and an especially personal stake in Bjorn’s journey.', 'body': '# The dwarf called Jimsko\n**Jimsko**, also known as **Jimmy Jim**, is a dwarf whose path crossed that of [[The Four Seasons]] in [[Port Llast]].\n\nHe is the father of [[Bjorn]]. Familiar to the adventurers from their earliest travels, Jimsko helped introduce [[Estephan]] to the company.\n\nFor all the great affairs of kings and gods, Jimsko is a reminder that this adventure began among ordinary people.', 'cover': '', 'aliases': ['Jimmy Jim'], 'facts': [['Ancestry', 'Dwarf'], ['Family', 'Bjorn'], ['First_known', 'Port Llast']], 'icon': '🍺'}, {'id': 'yulia', 'title': 'Princess Yulia', 'category': 'Characters', 'summary': 'A spirited princess of Neverwinter with silver hair and striking moonlike eyes.', 'body': '# The princess of Neverwinter\n**Princess Yulia** is a member of the royal family of [[Neverwinter]]. Her silver hair and moonlike eyes have made her memorable to those who have met her.\n\nDespite royal expectations, Yulia is known for her lively spirit, willingness to speak her mind, and concern for the people beyond the palace walls.\n\nHer story has begun to intersect with that of [[The Four Seasons]].', 'cover': '', 'aliases': ['Yulia'], 'facts': [['Title', 'Princess'], ['Home', 'Neverwinter']], 'icon': '♕'}, {'id': 'arven', 'title': 'King Arven I', 'category': 'Characters', 'summary': 'The young king of Thamor, trying to wear a crown in an uncertain age.', 'body': "# A young crown\n**King Arven I** rules [[Thamor]] at an age when most children are still discovering who they wish to become.\n\nThe king presided over a much-anticipated knighting ceremony in [[Crown Square]], attended by guards, residents, and visiting dignitaries. An attempted attack disrupted the festivities.\n\n## A contested future\nThamor faces outside pressure from [[Mourktar]], while the ominous [[Dragon's Due]] weighs on public conversation. With a child on the throne, every public appearance carries political weight.", 'cover': '', 'aliases': ['Arven'], 'facts': [['Title', 'King of Thamor'], ['Age', '13'], ['Residence', 'Thamor']], 'icon': '♛'}, {'id': 'cinder', 'title': 'Cinder', 'category': 'Characters', 'summary': 'An intriguing figure encountered amid the bustle and politics of Thamor.', 'body': '# A curious acquaintance\n**Cinder** is a figure the travelers met while exploring [[Thamor]]. Conversations with Cinder unfolded against a backdrop of crowded markets and preparations for [[King Arven I]]’s knighting ceremony.\n\nMuch about Cinder remains to be learned. This entry will grow as the company discovers more.', 'cover': '', 'aliases': [], 'facts': [['Encountered', 'Thamor']], 'icon': '✧'}, {'id': 'grath', 'title': 'Grath Erlkar', 'category': 'Characters', 'summary': 'A veteran leader and first captain associated with Port Llast.', 'body': "# The first captain\n**Grath Erlkar** is a prominent civic figure in [[Port Llast]], known as its First Captain.\n\nGrath's position places him among the townspeople most closely concerned with keeping this northern port functioning amid dangers at sea and ashore.", 'cover': '', 'aliases': [], 'facts': [['Title', 'First Captain'], ['Home', 'Port Llast'], ['Age', '58']], 'icon': '⚓'}, {'id': 'velka', 'title': 'Velka', 'category': 'Characters', 'summary': 'A dangerous adversary encountered in the caverns near Port Llast.', 'body': '# The cavern leader\n**Velka** led a hostile group encountered in the [[Caverns of Lior]], near [[Port Llast]].\n\nThe adventurers overcame Velka and captured their opponent alive during their investigation of the region.\n\nSee [[Campaign Chronicle]] for the surrounding events.', 'cover': '', 'aliases': [], 'facts': [['Associated_place', 'Caverns of Lior'], ['Status', 'Captured alive']], 'icon': '☠'}, {'id': 'wiwi', 'title': 'Wiwi', 'category': 'Characters', 'summary': 'A fairy whose appearance added a hint of the uncanny to the journey.', 'body': "# A flicker of fairy light\n**Wiwi** is a fairy known to [[The Four Seasons]].\n\nNot every story in the company's travels belongs to castles and grand designs. Some arrive on small wings, carried by the erratic magic of the fey.", 'cover': '', 'aliases': [], 'facts': [['Kind', 'Fairy']], 'icon': '🦋'}, {'id': 'brick', 'title': 'Brick', 'category': 'Characters', 'summary': 'A crab companion who has become a small but memorable part of the group.', 'body': '# The smallest adventurer?\n**Brick** is a **crab** companion of [[The Four Seasons]].\n\nLacking the stature of [[Bjorn]] or the spellcraft of [[Bramwell Elixor]], Brick nevertheless deserves his place in the adventuring record.\n\n*Yes, Brick is a crab.*', 'cover': '', 'aliases': [], 'facts': [['Species', 'Crab'], ['Association', 'The Four Seasons']], 'icon': '🦀'}, {'id': 'estephan', 'title': 'Estephan', 'category': 'Characters', 'summary': 'A mouse familiar and an unusual addition to the adventuring company.', 'body': '# A tiny fellow traveler\n**Estephan** is a mouse familiar introduced to [[The Four Seasons]] through [[Jimsko]] during their time in [[Port Llast]].\n\nA diminutive companion in a world of towering monsters and towering egos, Estephan has earned an entry of his own.', 'cover': '', 'aliases': [], 'facts': [['Species', 'Mouse'], ['Association', 'The Four Seasons']], 'icon': '🐭'}, {'id': 'port-llast', 'title': 'Port Llast', 'category': 'Locations', 'summary': 'A northern coastal settlement where the party’s adventures began.', 'body': '# Where the sea meets the story\n**Port Llast** lies on the northern [[Sword Coast]]. To travelers, it is a modest port town; to [[The Four Seasons]], it is where their common adventure truly began.\n\n## Places to know\n- [[The Net & Keg]] — an inn and tavern where stories and rumors mingle\n- [[Port Llast Lighthouse]] — a coastal landmark at the center of a disturbing investigation\n- [[Caverns of Lior]] — caverns beyond the town, where danger and discovery awaited\n\n## People\nAmong those connected with Port Llast are [[Grath Erlkar]] and [[Jimsko]].', 'cover': '', 'aliases': [], 'facts': [['Region', 'Sword Coast'], ['Type', 'Coastal settlement']], 'icon': '⚓'}, {'id': 'net-and-keg', 'title': 'The Net & Keg', 'category': 'Locations', 'summary': 'A familiar tavern and inn in Port Llast.', 'body': "# The Net & Keg\nThe **Net & Keg** is an inn and tavern in [[Port Llast]]. A place of food, talk, and passing travelers, it belongs to the earliest chapter of [[The Four Seasons]]' adventures.\n\n*What tales will the next patron bring through the door?*", 'cover': '', 'aliases': ['Net & Keg', 'Net and Keg'], 'facts': [['Location', 'Port Llast'], ['Type', 'Inn and tavern']], 'icon': '🍻'}, {'id': 'lighthouse', 'title': 'Port Llast Lighthouse', 'category': 'Locations', 'summary': 'The lighthouse at Port Llast, whose mystery led the party toward something far larger.', 'body': "# The light on the coast\nThe **Port Llast Lighthouse** watches the coastline near [[Port Llast]]. During the party's early investigation, the structure and the nearby shore became the focus of troubling activity.\n\nBeneath the lighthouse, the travelers found an old shrine connected with [[Selûne]]. The discoveries made there helped set them on the trail of the [[Moon Scroll]].", 'cover': '', 'aliases': ['the lighthouse', 'Lighthouse'], 'facts': [['Location', 'Port Llast'], ['Feature', 'Shrine beneath the lighthouse']], 'icon': '♜'}, {'id': 'caverns-lior', 'title': 'Caverns of Lior', 'category': 'Locations', 'summary': 'A network of dangerous caverns visited during the first leg of the adventure.', 'body': '# Beneath the earth\nThe **Caverns of Lior** are a cave system near [[Port Llast]]. During their search for answers, [[The Four Seasons]] entered the caverns and faced [[Velka]] and hostile inhabitants.\n\nThe journey through the caverns became one of the defining moments of their earliest adventures.', 'cover': '', 'aliases': [], 'facts': [['Region', 'Near Port Llast'], ['Type', 'Cavern system']], 'icon': '⛰'}, {'id': 'neverwinter', 'title': 'Neverwinter', 'category': 'Locations', 'summary': 'The celebrated Jewel of the North, a great city on the Sword Coast.', 'body': '# The Jewel of the North\n**Neverwinter** stands among the best-known cities of the [[Sword Coast]]. Its courts, markets, and avenues offer opportunity in equal measure to peril.\n\n[[The Four Seasons]] journeyed here following their adventures at [[Port Llast]]. Among the figures tied to its royal household is [[Princess Yulia]].\n\n## A city of many stories\nThe city is a place of temples, trade, politics, and countless lives whose stories continue whether or not adventurers are present.', 'cover': '', 'aliases': [], 'facts': [['Region', 'Sword Coast'], ['Type', 'Major city']], 'icon': '♜'}, {'id': 'luskan', 'title': 'Luskan', 'category': 'Locations', 'summary': 'A hard-edged northern city of ships, intrigue, and competing powers.', 'body': "# City of Sails\n**Luskan** is a northern city on the [[Sword Coast]], known for its ships and formidable reputation.\n\nIts history and rivalries form part of the wider world through which [[The Four Seasons]] travel. Not every secret of Luskan has yet found its way into the party's chronicle.", 'cover': '', 'aliases': [], 'facts': [['Region', 'Sword Coast'], ['Type', 'Port city']], 'icon': '⛵'}, {'id': 'sword-coast', 'title': 'Sword Coast', 'category': 'Locations', 'summary': 'A long stretch of western Faerûn, home to seaports, cities, and lonely roads.', 'body': "# Along the western shore\nThe **Sword Coast** is a region of western Faerûn where major trade cities stand beside old forests, seaside settlements, and dangerous stretches of wilderness.\n\nFor [[The Four Seasons]], the road here has connected [[Port Llast]], [[Neverwinter]], and the shadow of [[Luskan]].\n\nThe coast's bustle hides many smaller stories in its roadside inns, forgotten shrines, and rocky inlets.", 'cover': '', 'aliases': [], 'facts': [['Continent', 'Faerûn'], ['Type', 'Geographic region']], 'icon': '🗺'}, {'id': 'kestrel-ford', 'title': 'Kestrel Ford', 'category': 'Locations', 'summary': 'A lively road village where the adventurers chose their name.', 'body': '# The village at the ford\n**Kestrel Ford** is a village on the journey toward [[Thamor]]. Its roads carry merchants, local news, and travelers with different reasons to hurry onward.\n\nIt was around this stage of their travels that the party took the name [[The Four Seasons]].\n\nHere, ordinary village life briefly offered a contrast to the great affairs waiting in the city ahead.', 'cover': '', 'aliases': [], 'facts': [['Region', 'Road to Thamor'], ['Type', 'Village'], ['Noted_event', 'Naming of the Four Seasons']], 'icon': '🌾'}, {'id': 'thamor', 'title': 'Thamor', 'category': 'Locations', 'summary': 'A city of blue-and-gold banners, a child king, and uneasy celebrations.', 'body': "# Under blue and gold\n**Thamor** is a crowded city ruled by [[King Arven I]]. Visitors find lively streets, merchants, ceremony preparations, and the constant movement of a city hoping for a stable future.\n\n## The crown and its rivals\nThamor's independence has drawn pressure from [[Mourktar]], while stories of the [[Dragon's Due]] have troubled its residents.\n\n## A public gathering\nAt [[Crown Square]], the young king's knighting ceremony drew a large crowd and a formidable guard presence. [[The Four Seasons]] witnessed an attempted attack during the proceedings.\n\nThe party has also crossed paths with [[Cinder]] in the city.", 'cover': '', 'aliases': [], 'facts': [['Region', 'Threskel'], ['Ruler', 'King Arven I'], ['Known_for', 'The knighting ceremony']], 'icon': '🏰'}, {'id': 'crown-square', 'title': 'Crown Square', 'category': 'Locations', 'summary': 'The ceremonial heart of Thamor and the setting of a memorable knighting.', 'body': "# A square beneath the banners\n**Crown Square** is a prominent public gathering place in [[Thamor]]. During [[King Arven I]]'s knighting ceremony, the square thronged with guards, nobles, townsfolk, and visiting spectators.\n\nAn arrow and the appearance of assailants cast a sudden shadow over the celebration. [[Bramwell Elixor]] was among those who reacted to the danger.", 'cover': '', 'aliases': [], 'facts': [['City', 'Thamor'], ['Known_event', 'Knighting ceremony']], 'icon': '⚜'}, {'id': 'mourktar', 'title': 'Mourktar', 'category': 'Locations', 'summary': 'A rival power whose dealings with Thamor have become a topic of concern.', 'body': "# Beyond Thamor\n**Mourktar** is a distant center of power mentioned in connection with [[Thamor]]'s political situation.\n\nThe city and its envoys are discussed in the context of competing claims, diplomatic pressure, and the future of [[King Arven I]]'s reign.\n\nWhat these tensions mean for the adventurers remains to be seen.", 'cover': '', 'aliases': [], 'facts': [['Associated_with', 'Thamor'], ['Type', 'City / political power']], 'icon': '⚖'}, {'id': 'blackreach', 'title': 'Blackreach', 'category': 'Locations', 'summary': 'A place remembered from the party’s travels before they reached Kestrel Ford.', 'body': '# A road behind them\n**Blackreach** is a location in the recent travels of [[The Four Seasons]], before their arrival at [[Kestrel Ford]].\n\nThis is a short entry, ready to be expanded with player-confirmed recollections and discoveries.', 'cover': '', 'aliases': [], 'facts': [['Status', 'Previously visited']], 'icon': '☁'}, {'id': 'selune', 'title': 'Selûne', 'category': 'Deities & Lore', 'summary': 'The Moonmaiden, deity of moonlight, whose name threads through the campaign.', 'body': "# The Moonmaiden\n**Selûne**, the Moonmaiden, is a deity associated with the moon, guiding light, and those who seek their way through darkness.\n\nA shrine beneath the [[Port Llast Lighthouse]] and the discovery of the [[Moon Scroll]] drew the attention of [[The Four Seasons]] to the goddess and her history.\n\nSelûne's ancient opposition to [[Shar]] lies at the heart of many stories in the world.", 'cover': '', 'aliases': ['Selune', 'Moonmaiden'], 'facts': [['Sphere', 'Moon and moonlight'], ['Rival', 'Shar']], 'icon': '☾'}, {'id': 'shar', 'title': 'Shar', 'category': 'Deities & Lore', 'summary': 'The Lady of Loss, a deity associated with darkness and secrets.', 'body': '# The Lady of Loss\n**Shar** is a deity often associated with darkness, loss, and hidden things.\n\nHer legendary conflict with [[Selûne]] is known far beyond temples and ancient manuscripts. The [[Moon Scroll]] has brought echoes of that conflict close to [[The Four Seasons]].\n\nMuch remains unknown about what this history may mean for the present.', 'cover': '', 'aliases': [], 'facts': [['Sphere', 'Darkness and loss'], ['Rival', 'Selûne']], 'icon': '◈'}, {'id': 'helm', 'title': 'Helm', 'category': 'Deities & Lore', 'summary': 'The Watcher, god of guardians, duty, and vigilance.', 'body': '# The Watcher\n**Helm** is the god of watchfulness and guardianship, revered by those sworn to stand between danger and the people they protect.\n\n[[Bramwell Elixor]] serves Helm as a cleric, although questions of doctrine and duty have not always led him down the easiest path.', 'cover': '', 'aliases': [], 'facts': [['Sphere', 'Guardians and vigilance'], ['Known_follower', 'Bramwell Elixor']], 'icon': '🛡'}, {'id': 'moon-scroll', 'title': 'Moon Scroll', 'category': 'Artifacts', 'summary': 'An ancient scroll whose discovery changed the direction of the party’s journey.', 'body': "# A recovered mystery\nThe **Moon Scroll** is an ancient document recovered during the early adventures of [[The Four Seasons]]. The party's investigation of the [[Port Llast Lighthouse]] and [[Caverns of Lior]] placed the scroll at the center of their journey.\n\nThe writing has been connected with ancient Netherese language and with the histories of [[Selûne]] and [[Shar]].\n\n## What remains unknown\nIts full implications are not yet part of the public chronicle. This entry records only what the travelers have learned.", 'cover': '', 'aliases': ['the scroll', 'prophecy scroll'], 'facts': [['Type', 'Ancient scroll'], ['Found_during', 'Port Llast arc']], 'icon': '📜'}, {'id': 'dragons-due', 'title': "Dragon's Due", 'category': 'Deities & Lore', 'summary': 'An ominous obligation discussed in connection with Thamor and a red dragon.', 'body': "# A shadow over the city\nThe phrase **Dragon's Due** is spoken around [[Thamor]] as a source of apprehension.\n\nIt is associated with reports of a powerful red dragon and concerns over the city's security and autonomy. Political tensions involving [[Mourktar]] have only increased uncertainty.\n\nHow much is rumor, how much is threat, and how much is politics remains to be discovered by [[The Four Seasons]].", 'cover': '', 'aliases': ['Dragons Due', 'the Due'], 'facts': [['Associated_place', 'Thamor'], ['Nature', 'Unresolved threat']], 'icon': '🐉'}, {'id': 'how-to-use', 'title': 'How to Use This Wiki', 'category': 'Guides', 'summary': 'A quick introduction to browsing and contributing to the living campaign encyclopedia.', 'body': "# Welcome to the archive\nThis wiki is written for players of **The Daughter of the Moon**. It grows as the party discovers people, places, artifacts, and stories.\n\n## Finding articles\nUse the **Search** field, browse the category library, or follow highlighted names inside any article. Names that already have entries are automatically linked. You can also write an explicit link with `[[Neverwinter]]` or `[[Neverwinter|the city]]`.\n\n## Editing\nOpen an article and select **Edit article**. New entries can be created from **New entry**. Changes are saved as local drafts first; publishing to GitHub requires an authorized editor's credential.\n\n## Images\nEditors can attach or replace images and insert them directly into an article. Images are stored with the project when the changes are published.\n\n## A spoiler-safe book\nUnrevealed lore and DM plans do **not** belong in this public archive.", 'cover': '', 'aliases': [], 'facts': [['Access', 'Public read / authorized edit']], 'icon': '✎'}]}

